custom_css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600&family=Merriweather:ital,wght@0,300;0,400;0,600;1,400&display=swap');

/* ============================================================
   RUN, LITTLE MOUSE... — готическая тема для SillyTavern
   Структура родной темы сохранена 1:1, изменены палитра, фон,
   шрифты и иконки.

   Сделано с любовью ✦ Selena's Tavern ✦
   https://satsvi97.github.io/selena/
   ============================================================ */

/* ====== ОБЩИЙ ФОН И ШРИФТ ====== */
body {
    font-family: 'Merriweather', Georgia, serif !important;
    font-weight: 400 !important;
    background-color: #04070A !important;
    background-image: url('https://satsvi97.github.io/run-little-mouse/assets/bg.png') !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    color: #E4EAEE !important;
}

/* ====== ЦЕНТРОВКА ЧАТА ======
   ST (MovingUI) хранит перетащенную позицию панели и подставляет её в left —
   из-за этого чат уезжает вправо. Возвращаем по центру. */
#sheld {
    left: 50% !important;
    margin: 0 !important;
    transform: translateX(-50%) !important;
    width: min(1080px, 76vw) !important;
}

/* ====== СТАНДАРТНЫЕ СООБЩЕНИЯ И ПЛАШКИ ====== */
body.bubblechat .mes, .mes {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    border: none !important;
    padding: 16px 12px;
}

#chat .mes_block {
    background: rgba(16, 28, 36, 0.62) !important;
    backdrop-filter: blur(10px) !important;
    border-radius: 12px !important;
    border: 1px solid rgba(110, 138, 160, 0.34) !important;
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.5) !important;
    padding: 20px !important;
    width: 95% !important;
    margin: 0 auto !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
}

/* ====== АВАТАРКИ: ПОЛАРОИД ======
   Баннер — avatar-frame.png: сцена + рамка полароида, внутри рамки прозрачное «окно».
   Фото персонажа лежит ПОД рамкой ровно в окне, рамка (слой ::after) накрывает его сверху. */
.mes .mesAvatarWrapper::after { display: none !important; content: none !important; }

.mes .avatar {
    position: relative !important;
    flex: 0 0 auto !important;
    width: 250px !important;
    height: 250px !important;
    margin: 0 auto 10px auto !important;
    background: url('https://satsvi97.github.io/run-little-mouse/assets/avatar-frame.png') center center / cover no-repeat !important;
    border: none !important;
    border-radius: 14px !important;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.6), 0 0 15px rgba(140, 180, 205, 0.18) !important;
    overflow: hidden !important;
}

.mes .avatar img {
    position: absolute !important;
    z-index: 1 !important;
    left: 24.31% !important;
    top: 11.01% !important;
    width: 51.26% !important;
    height: 45.28% !important;
    max-width: none !important;
    max-height: none !important;
    margin: 0 !important;
    object-fit: cover !important;
    object-position: 50% 25% !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    -webkit-mask-image: none !important;
    mask-image: none !important;
    transform: none !important;
}

/* рамка поверх фото: перекрывает края снимка, в окне прозрачна */
.mes .avatar::after {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    inset: 0 !important;
    z-index: 2 !important;
    background: url('https://satsvi97.github.io/run-little-mouse/assets/avatar-frame.png') center center / cover no-repeat !important;
    pointer-events: none !important;
}

@media screen and (min-width: 1024px) {
    .mes .avatar {
        width: 850px !important;
        height: auto !important;
        aspect-ratio: 850 / 349 !important;
        background-size: 100% 100% !important;
        border-radius: 16px !important;
    }
    .mes .avatar img {
        left: 39.41% !important;
        top: 11.01% !important;
        width: 21.06% !important;
        height: 45.28% !important;
    }
    .mes .avatar::after {
        background-size: 100% 100% !important;
    }
}

/* ====== ИМЕНА И ВРЕМЯ ====== */
.mes_block .ch_name { display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: center !important; padding: 10px !important; width: 100% !important; margin-bottom: 15px; }
.name_text { font-family: 'Playfair Display', Georgia, serif !important; font-weight: 600 !important; font-size: 1.4em !important; color: #DCE6ED !important; letter-spacing: 2px !important; text-transform: uppercase !important; text-shadow: 0 0 10px rgba(140, 176, 200, 0.45) !important; }
.name_text::before, .name_text::after { content: "✦" !important; font-size: 0.8em !important; margin: 0 8px !important; color: rgba(150, 180, 200, 0.75) !important; }
.timestamp { color: rgba(128, 149, 166, 0.9) !important; font-family: 'Merriweather', Georgia, serif !important; font-style: italic !important; font-size: .85em !important; text-align: center !important; }

/* ====== СЧЕТЧИКИ (под аватаркой, по центру) ======
   .avatar занимает целую строку, псевдоэлемент-разрыв ::before сдвигает
   счётчики (#ID, таймер, токены) на следующую строку, justify-content: center
   центрует и баннер, и ряд счётчиков. */
.mesAvatarWrapper {
    position: relative !important;
    display: flex !important;
    flex-wrap: wrap !important;
    justify-content: center !important;
    align-items: center !important;
    width: 100% !important;
    min-height: 0 !important;
    gap: 6px 8px !important;
    padding: 0 !important;
    margin: 0 0 6px 0 !important;
}
.mesAvatarWrapper > .avatar { flex: 0 0 auto !important; order: 0 !important; display: flex !important; justify-content: center !important; margin: 0 !important; }
.mesAvatarWrapper::before { content: '' !important; flex-basis: 100% !important; height: 0 !important; order: 1 !important; }
.mesAvatarWrapper > .mesIDDisplay, .mesAvatarWrapper > .mes_timer, .mesAvatarWrapper > .tokenCounterDisplay {
    order: 2 !important;
    display: inline-flex !important; align-items: center !important; max-height: 20px !important; padding: 4px 12px !important; border-radius: 10px !important; font-size: 0.78em !important; border: 1px solid rgba(110, 138, 160, 0.34) !important; color: #9FB8CC !important; background: transparent !important;
}

/* ====== ТЕКСТ ====== */
.mes_text { background: transparent !important; padding: 16px 14px; font-size: 1em !important; font-weight: 500 !important; line-height: 1.7 !important; color: #EDF2F5 !important; text-shadow: 0px 1px 2px rgba(0, 0, 0, 0.8) !important; width: 100% !important; border: none !important; }
.mes_text em, .mes_text i { font-style: italic !important; color: #A9BECB !important; background: transparent !important; }

/* ========================================================= */
/* ====== ПЛАШКИ: ДВА ХАРАКТЕРА ====== */
/* ОН — холодный лист: сталь, арка сверху, свечная кромка слева, */
/* обтрепанный низ, метка rec.                                   */
/* ОНА — записка: тёплая роза, загнутый уголок, кромка справа.    */
/* ========================================================= */
#chat .mes { position: relative !important; animation: nwSettle .55s cubic-bezier(.2, .7, .3, 1) both !important; }
@keyframes nwSettle {
    from { opacity: 0; transform: translateY(6px); }
    to   { opacity: 1; transform: none; }
}

#chat .mes_block { position: relative !important; overflow: hidden !important; isolation: isolate !important; }
/* бумажное зерно поверх плашки — очень мелкое, почти незаметное */
#chat .mes_block::before {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    z-index: 1 !important;
    pointer-events: none !important;
    opacity: 0.45 !important;
    mix-blend-mode: overlay !important;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='140' height='140' filter='url(%23n)' opacity='0.45'/></svg>") !important;
}
/* текст и шапка — над зерном */
#chat .mes_block .ch_name, #chat .mes_block .mes_text { position: relative !important; z-index: 2 !important; }

/* ---------- ОН ---------- */
#chat .mes[is_user="false"] .mes_block {
    background:
        radial-gradient(120% 170% at 10% 0%, rgba(40, 46, 44, 0.30), rgba(16, 27, 35, 0) 48%),
        linear-gradient(180deg, rgba(17, 28, 37, 0.94), rgba(8, 15, 21, 0.96)) !important;
    border: 1px solid rgba(110, 138, 160, 0.26) !important;
    border-left: 2px solid rgba(217, 164, 106, 0.50) !important;
    border-radius: 24px 24px 8px 8px !important;
    box-shadow: inset 26px 0 38px -30px rgba(217, 164, 106, 0.85), -12px 0 30px -18px rgba(217, 164, 106, 0.85), 0 16px 40px rgba(0, 0, 0, 0.55) !important;
    /* обтрепанный край: маска с шумом */
    -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='600' height='240'><filter id='m'><feTurbulence type='fractalNoise' baseFrequency='0.02 0.09' numOctaves='2' seed='11'/><feDisplacementMap in='SourceGraphic' scale='5' xChannelSelector='R' yChannelSelector='G'/></filter><rect x='2' y='2' width='596' height='236' rx='20' fill='white' filter='url(%23m)'/></svg>");
    mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='600' height='240'><filter id='m'><feTurbulence type='fractalNoise' baseFrequency='0.02 0.09' numOctaves='2' seed='11'/><feDisplacementMap in='SourceGraphic' scale='5' xChannelSelector='R' yChannelSelector='G'/></filter><rect x='2' y='2' width='596' height='236' rx='20' fill='white' filter='url(%23m)'/></svg>");
    -webkit-mask-size: 100% 100% !important;
    mask-size: 100% 100% !important;
}
#chat .mes[is_user="false"] .mes_block .ch_name::before {
    content: 'rec' !important;
    position: absolute !important;
    top: -12px !important;
    right: -6px !important;
    font-family: 'Consolas', 'Courier New', monospace !important;
    font-size: 9px !important;
    letter-spacing: 2px !important;
    text-transform: uppercase !important;
    color: rgba(200, 65, 79, 0.85) !important;
    text-shadow: 0 0 8px rgba(163, 32, 47, 0.5) !important;
    animation: nwRecBlink 2.4s ease-in-out infinite !important;
    pointer-events: none !important;
}
@keyframes nwRecBlink { 0%, 62%, 100% { opacity: 1; } 78% { opacity: 0.25; } }

/* ---------- ОНА ---------- */
#chat .mes[is_user="true"] .mes_block {
    background:
        radial-gradient(120% 170% at 88% 0%, rgba(92, 30, 38, 0.42), rgba(24, 18, 22, 0) 50%),
        linear-gradient(200deg, rgba(30, 20, 25, 0.94), rgba(10, 16, 22, 0.96)) !important;
    border: 1px solid rgba(163, 32, 47, 0.22) !important;
    border-right: 2px solid rgba(163, 32, 47, 0.55) !important;
    border-radius: 6px 6px 22px 22px !important;
    box-shadow: 12px 0 30px -18px rgba(163, 32, 47, 0.85), 0 16px 40px rgba(0, 0, 0, 0.55) !important;
}
/* загнутый уголок, как у вырванной страницы */
#chat .mes[is_user="true"] .mes_block::after {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    width: 30px !important;
    height: 30px !important;
    z-index: 3 !important;
    pointer-events: none !important;
    background: linear-gradient(225deg, rgba(48, 20, 26, 0.95) 0 50%, rgba(255, 255, 255, 0.07) 50% 100%) !important;
    border-radius: 0 0 0 3px !important;
}
#chat .mes[is_user="true"] .mes_text em, #chat .mes[is_user="true"] .mes_text i { color: #C79AA2 !important; }

/* имя и время: у неё — розовые нотки, у него — сталь */
#chat .mes[is_user="true"] .name_text { color: #E8D9DC !important; text-shadow: 0 0 10px rgba(200, 65, 79, 0.35) !important; }
#chat .mes[is_user="true"] .name_text::before, #chat .mes[is_user="true"] .name_text::after { color: rgba(200, 120, 130, 0.65) !important; }
#chat .mes .timestamp {
    font-family: 'Consolas', 'Courier New', monospace !important;
    font-style: normal !important;
    font-size: 0.72em !important;
    letter-spacing: 1.5px !important;
    text-transform: uppercase !important;
    color: rgba(128, 149, 166, 0.85) !important;
}
#chat .mes .timestamp::before {
    content: '●' !important;
    font-size: 0.7em !important;
    margin-right: 6px !important;
    color: rgba(200, 65, 79, 0.9) !important;
}

/* разделитель-ромб между сообщениями */
#chat .mes + .mes::before {
    content: '' !important;
    position: absolute !important;
    top: -2px !important;
    left: 50% !important;
    width: 5px !important;
    height: 5px !important;
    transform: translateX(-50%) rotate(45deg) !important;
    background: rgba(110, 138, 160, 0.45) !important;
    box-shadow: 0 0 8px rgba(140, 176, 200, 0.25) !important;
    pointer-events: none !important;
}

/* кнопки-печати */
#chat .mes_buttons .mes_button {
    border-radius: 50% !important;
    width: 22px !important;
    height: 22px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: radial-gradient(circle at 34% 28%, rgba(217, 164, 106, 0.30), rgba(120, 78, 40, 0.16) 60%, rgba(10, 18, 24, 0.9) 100%) !important;
    border: 1px solid rgba(217, 164, 106, 0.28) !important;
    box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.10), 0 0 8px rgba(217, 164, 106, 0.12) !important;
    color: rgba(230, 214, 196, 0.75) !important;
    margin: 0 3px !important;
    transition: box-shadow .25s ease, border-color .25s ease, transform .2s ease !important;
}
#chat .mes_buttons .mes_button:hover {
    box-shadow: 0 0 12px rgba(217, 164, 106, 0.45), inset 0 1px 1px rgba(255, 255, 255, 0.16) !important;
    transform: translateY(-1px) !important;
}
#chat .mes[is_user="true"] .mes_buttons .mes_button {
    background: radial-gradient(circle at 34% 28%, rgba(200, 65, 79, 0.35), rgba(122, 21, 32, 0.25) 60%, rgba(12, 18, 24, 0.9) 100%) !important;
    border-color: rgba(163, 32, 47, 0.42) !important;
    color: rgba(240, 210, 210, 0.8) !important;
}
#chat .mes[is_user="true"] .mes_buttons .mes_button:hover {
    box-shadow: 0 0 12px rgba(163, 32, 47, 0.55), inset 0 1px 1px rgba(255, 255, 255, 0.16) !important;
}

@media (prefers-reduced-motion: reduce) {
    #chat .mes { animation: none !important; }
    #chat .mes[is_user="false"] .mes_block .ch_name::before { animation: none !important; }
}

/* ====== НИЖНЯЯ ПАНЕЛЬ ВВОДА ====== */
#form_sheld, #send_form, #nonQRFormItems, #send_textarea { background-color: #080F15 !important; background-image: none !important; }
#send_form { border-top: 1px solid rgba(110, 138, 160, 0.3) !important; padding: 8px !important; }
#send_textarea { font-family: 'Merriweather', Georgia, serif !important; font-size: 14px !important; color: #E4EAEE !important; -webkit-appearance: none !important; box-shadow: none !important; border-radius: 0 !important; }
#nonQRFormItems { position: relative !important; }
/* подсказка в поле ввода: цитата Аделайн, тёмно-красным с мягким свечением */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "Run, if I catch you, I ᶠᶸᶜᵏᵧₒᵤ!𓂃🪶" !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: #D0405A !important;
    font-family: 'Playfair Display', Georgia, serif !important;
    font-size: 17px !important;
    font-style: italic !important;
    letter-spacing: 0.4px !important;
    white-space: nowrap !important;
    pointer-events: none !important;
    text-shadow: 0 0 10px rgba(163, 32, 47, 0.85), 0 0 24px rgba(163, 32, 47, 0.45) !important;
    z-index: 20 !important;
}

/* прячем родной placeholder ST — у нас своя строка выше */
#send_textarea::placeholder {
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    opacity: 0 !important;
}

/* ====== ПОЛЗУНКИ, ЧЕКБОКСЫ, СКРОЛЛБАРЫ ====== */
input[type="range"] { -webkit-appearance: none !important; background: linear-gradient(to right, rgba(110, 138, 160, 0.35), rgba(159, 184, 204, 0.55)) !important; height: 8px !important; border-radius: 4px !important; }
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none !important; width: 32px !important; height: 32px !important; background: transparent url('data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 32 32"><text x="16" y="24" text-anchor="middle" font-size="28" fill="rgb(159,184,204)" style="font-family: Arial;">✦</text></svg>') center/contain no-repeat !important; border: none !important; cursor: pointer !important; filter: drop-shadow(0 2px 6px rgba(110, 138, 160, 0.45)) !important; }
input[type="checkbox"] { -webkit-appearance: none !important; appearance: none !important; width: 22px !important; height: 22px !important; border: 2px solid rgba(126, 154, 176, 0.55) !important; border-radius: 6px !important; background-color: transparent !important; display: inline-block !important; position: relative !important; cursor: pointer !important; vertical-align: middle !important; margin-right: 10px !important; }
input[type="checkbox"]:checked { background-color: #9FB8CC !important; border-color: #9FB8CC !important; }
input[type="checkbox"]:checked::after { content: '✦' !important; position: absolute !important; top: 50% !important; left: 50% !important; transform: translate(-50%, -50%) !important; color: #080F15 !important; font-size: 16px !important; font-weight: bold !important; line-height: 1 !important; }
#chat .mes input[type="checkbox"], .mesAvatarWrapper input[type="checkbox"] { display: none !important; }
::-webkit-scrollbar-thumb { background: rgba(110, 138, 160, 0.45) !important; border-radius: 3px; }
::-webkit-scrollbar-track { background: rgba(4, 7, 10, 0.55) !important; }

/* ====== КНОПКА ОТПРАВКИ (СТРЕЛОЧКА) ====== */
#send_but {
    background: transparent !important; background-image: none !important; border: none !important; box-shadow: none !important;
    position: relative !important; width: 45px !important; height: 45px !important; padding: 0 !important; overflow: visible !important;
}
#send_but::before, #send_but::after { display: none !important; content: none !important; background: none !important; }
#send_but * { display: none !important; visibility: hidden !important; opacity: 0 !important; }
#send_but::after {
    content: '' !important; display: block !important; position: absolute !important; top: 50% !important; left: 50% !important;
    transform: translate(-50%, -50%) !important;
    width: 26px !important; height: 26px !important;
    background: url('data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="rgb(159,184,204)" d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>') no-repeat center / contain !important;
    filter: drop-shadow(0 0 8px rgba(160, 195, 215, 0.75)) !important;
    z-index: 9999 !important; pointer-events: none !important; visibility: visible !important; opacity: 1 !important;
    transition: filter 0.3s ease !important;
}
#send_but:hover::after {
    filter: drop-shadow(0 0 10px rgba(217, 164, 106, 0.9)) !important;
}
/* самолётик виден всегда: без соединения с API — приглушён, при генерации прячется (кольцо) */
#send_but.displayNone { display: block !important; }

/* во время генерации ST прячет самолётик сразу тремя способами — ловим все:
   body[data-generating], body[data-swiping] и кнопку «стоп» с inline display:flex */
body[data-generating="true"] #send_but,
body[data-generating="true"] #send_but.displayNone,
body[data-swiping="true"] #send_but,
body[data-swiping="true"] #send_but.displayNone,
body:has(#mes_stop[style*="flex"]) #send_but,
body:has(#mes_stop[style*="flex"]) #send_but.displayNone { display: none !important; }

/* страховка: если кнопка «стоп» почему-то не показалась —
   сердце рисуется прямо в самом самолётике (та же точка, без сдвига) */
body[data-generating="true"]:not(:has(#mes_stop[style*="flex"])) #send_but,
body[data-generating="true"]:not(:has(#mes_stop[style*="flex"])) #send_but.displayNone,
body[data-swiping="true"]:not(:has(#mes_stop[style*="flex"])) #send_but,
body[data-swiping="true"]:not(:has(#mes_stop[style*="flex"])) #send_but.displayNone { display: block !important; }
body[data-generating="true"]:not(:has(#mes_stop[style*="flex"])) #send_but::after,
body[data-swiping="true"]:not(:has(#mes_stop[style*="flex"])) #send_but::after {
    background-image: var(--nw-heart) !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    width: 30px !important;
    height: 30px !important;
    border: none !important;
    border-radius: 0 !important;
    animation: nwHeartbeat 1.8s ease-in-out infinite !important;
    opacity: 1 !important;
}
#send_but.displayNone::after { opacity: 0.35 !important; filter: none !important; }
#send_but.displayNone:hover::after { opacity: 0.7 !important; filter: drop-shadow(0 0 8px rgba(160, 195, 215, 0.75)) !important; }

/* правило, прятавшее самолётик при открытой панели персонажей, убрано:
   в ST 1.18 панель открыта почти всегда — кнопка пропадала совсем */

/* ====== НИЖНИЕ ИКОНКИ СЛЕВА: тематические (по макету) ======
   «розетка» (шестерёнка-цветок) — меню, искра — расширения, квадрат — персона. */
#extensionsMenuButton { background: none !important; border: none !important; position: relative !important; font-size: 0 !important; }
#extensionsMenuButton::before, #extensionsMenuButton i, #extensionsMenuButton img { display: none !important; }
#extensionsMenuButton::after {
