/* ====== СТОП-ГЕНЕРАЦИЯ: пока ждём ответ — сердцебиение ====== */
/* состояние .generating = ST показывает «стоп», самолётик прячется,
   на его месте бьётся сердце (луп-даб: два удара и пауза) */
#mes_stop {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    position: relative !important;
    width: 44px !important;
    height: 44px !important;
    padding: 0 !important;
    font-size: 0 !important;
}
#mes_stop * { display: none !important; }
#mes_stop::after {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    inset: 0 !important;
    margin: auto !important;
    width: 30px !important;
    height: 30px !important;
    background: var(--nw-heart) center / contain no-repeat !important;
    animation: nwHeartbeat 1.8s ease-in-out infinite !important;
    pointer-events: none !important;
}
@keyframes nwHeartbeat {
    0%   { transform: scale(1);    filter: drop-shadow(0 0 5px rgba(196, 58, 74, 0.55)); }
    7%   { transform: scale(1.24); filter: drop-shadow(0 0 13px rgba(232, 96, 110, 0.95)); }
    14%  { transform: scale(1.04); filter: drop-shadow(0 0 7px rgba(196, 58, 74, 0.65)); }
    22%  { transform: scale(1.16); filter: drop-shadow(0 0 11px rgba(232, 96, 110, 0.85)); }
    34%  { transform: scale(1);    filter: drop-shadow(0 0 5px rgba(196, 58, 74, 0.5)); }
    100% { transform: scale(1);    filter: drop-shadow(0 0 5px rgba(196, 58, 74, 0.5)); }
}

/* ====== ВЕРХНИЕ ИКОНКИ ====== */
:root {
    --icon-size: 38px;
    /* сердце для состояния генерации (родное #A3202F, чуть светлее для свечения) */
    --nw-heart: url('data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="rgb(214,74,90)" d="M12 20.7 C12 20.7 3.3 15.2 3.3 9.5 C3.3 6.7 5.5 4.5 8.3 4.5 C10 4.5 11.4 5.4 12 6.6 C12.6 5.4 14 4.5 15.7 4.5 C18.5 4.5 20.7 6.7 20.7 9.5 C20.7 15.2 12 20.7 12 20.7 Z"/></svg>');
}
/* ряд иконок: компактный, по центру, ширина с чат */
/* ряд иконок: растянут вдоль всей панели топбара */
#top-settings-holder { width: min(1080px, 76vw) !important; margin: 4px auto 0 !important; left: 0 !important; justify-content: space-evenly !important; gap: 0 !important; }
#top-settings-holder > .drawer { width: auto !important; flex: 0 0 auto !important; }
#top-settings-holder .drawer-toggle { width: var(--icon-size) !important; min-width: 0 !important; padding: 0 !important; }
#top-settings-holder .drawer-header { width: var(--icon-size) !important; }
/* порядок кнопок — как в макете: пресеты, профиль соединения, форматирование,
   лорбуки, настройки пользователя (центр), фоны, расширения, персона, персонаж */
#ai-config-button { order: 1 !important; }
#sys-settings-button { order: 2 !important; }
#advanced-formatting-button { order: 3 !important; }
#WI-SP-button { order: 4 !important; }
#user-settings-button { order: 5 !important; }
#backgrounds-button { order: 6 !important; }
#extensions-settings-button { order: 7 !important; }
#persona-management-button { order: 8 !important; }
#rightNavHolder { order: 9 !important; }
/* боковые панели при открытии: нормальная ширина вместо узкой колонки */
#ai-config-button .drawer-content { width: min(480px, 42vw) !important; left: 0 !important; }
#rightNavHolder .drawer-content { width: min(420px, 36vw) !important; right: 0 !important; }
/* верхние панели: центрируем по экрану, чтобы не обрывались за краем */
#top-settings-holder > .drawer:not(#ai-config-button):not(#rightNavHolder) .drawer-content {
    left: 50% !important;
    transform: translateX(-50%) !important;
    width: min(1700px, 96vw) !important;
}
#leftNavDrawerIcon, #rightNavDrawerIcon, #sys-settings-button .drawer-icon, #advanced-formatting-button .drawer-icon, #WI-SP-button .drawer-icon, #user-settings-button .drawer-icon, #backgrounds-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon { font-size: 0 !important; color: transparent !important; width: var(--icon-size) !important; height: var(--icon-size) !important; display: flex !important; align-items: center !important; justify-content: center !important; }

/* ========================================================= */
