.mes[is_user="false"] + .mes[is_user="false"] .mesAvatarWrapper { display: none !important; }
.mes[is_user="false"] + .mes[is_user="false"] .ch_name { display: none !important; }
.mes[is_user="false"] + .mes[is_user="false"] .mes_block {
