#load-spinner {
    --spinner-size: 68px !important;
    font-size: 0 !important;
    animation: none !important;
}
/* родной спиннер ST внутри контейнера не нужен */
#load-spinner > * { display: none !important; }
#load-spinner::before {
    content: '' !important;
    display: block !important;
    width: 68px !important;
    height: 68px !important;
    margin: 0 auto !important;
    background: var(--nw-heart) center / contain no-repeat !important;
    animation: nwHeartbeatBig 1.8s ease-in-out infinite !important;
}
@keyframes nwHeartbeatBig {
    0%   { transform: scale(1);    filter: drop-shadow(0 0 10px rgba(196, 58, 74, 0.55)); }
    7%   { transform: scale(1.22); filter: drop-shadow(0 0 26px rgba(232, 96, 110, 0.95)); }
    14%  { transform: scale(1.04); filter: drop-shadow(0 0 14px rgba(196, 58, 74, 0.65)); }
    22%  { transform: scale(1.14); filter: drop-shadow(0 0 22px rgba(232, 96, 110, 0.85)); }
    34%  { transform: scale(1);    filter: drop-shadow(0 0 10px rgba(196, 58, 74, 0.5)); }
    100% { transform: scale(1);    filter: drop-shadow(0 0 10px rgba(196, 58, 74, 0.5)); }
}

/* логотип SillyTavern со сплэша убираем совсем */
.splash-logo { display: none !important; }

/* текст «Initializing…» — в стиле темы, чтобы экран не выглядел голым */
.splash-message {
    font-family: 'Playfair Display', Georgia, serif !important;
    font-size: 1rem !important;
    font-weight: 400 !important;
    font-style: italic !important;
    letter-spacing: 3px !important;
    text-transform: uppercase !important;
    color: rgba(159, 184, 204, 0.85) !important;
    text-shadow: 0 0 14px rgba(140, 176, 200, 0.35) !important;
}

#preloader, #loader {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    margin: 0 !important;
    background: #04070A !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 2.2rem !important;
}
#preloader *, #loader * { background-color: transparent !important; }

/* ========================================================= */
/* ====== ГОТИЧЕСКИЙ ФОН ДЛЯ ПАНЕЛИ ВВОДА ======= */
/* Свеча в левом нижнем углу (тёплое неровное мерцание),      */
/* отсвет тёмной розы справа, по полосе плывёт холодный       */
/* туман, снизу вверх поднимаются редкие угли.                */
/* ========================================================= */
#send_form {
    position: relative !important;
    overflow: hidden !important;
    background:
        radial-gradient(140% 300% at -4% 132%, rgba(198, 132, 66, 0.26), rgba(34, 26, 24, 0) 54%),
        radial-gradient(85% 220% at 102% 118%, rgba(163, 32, 47, 0.18), rgba(30, 20, 22, 0) 58%),
        radial-gradient(110% 220% at 74% -70%, rgba(128, 168, 200, 0.17), transparent 72%),
        linear-gradient(180deg, #0A1319 0%, #070D12 58%, #050A0E 100%) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    border: 1px solid rgba(110, 138, 160, 0.32) !important;
    border-radius: 12px !important;
    margin: 10px auto !important;
    width: 95% !important;
    box-shadow: inset 0 0 46px rgba(0, 0, 0, 0.85), inset 0 1px 0 rgba(150, 190, 215, 0.10), 0 -5px 20px rgba(0, 0, 0, 0.35) !important;
}
#form_sheld, #nonQRFormItems, #send_textarea {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    position: relative !important;
    z-index: 2 !important;
}
/* слой 1: туман — четыре «клуба», ползущие по полосе с разной скоростью,
   поверх них неровное мерцание свечи (как будто огонь дрогнул) */
#send_form::before {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    z-index: 0 !important;
    pointer-events: none !important;
    background-image:
        radial-gradient(ellipse 150px 70px at 20% 80%, rgba(158, 198, 226, 0.10), transparent 70%),
        radial-gradient(ellipse 120px 55px at 48% 30%, rgba(140, 180, 212, 0.075), transparent 72%),
        radial-gradient(ellipse 170px 75px at 76% 78%, rgba(168, 204, 230, 0.09), transparent 70%),
        radial-gradient(ellipse 110px 50px at 96% 40%, rgba(140, 180, 212, 0.07), transparent 72%) !important;
    background-size: 640px 200%, 460px 200%, 560px 200%, 380px 200% !important;
    background-repeat: repeat-x !important;
    /* без !important: иначе анимация background-position не работает */
    background-position: 0 0, 0 0, 0 0, 0 0;
    filter: blur(3px) !important;
    animation: nwFogDrift 52s linear infinite, nwCandleFlicker 7s ease-in-out infinite alternate !important;
}
@keyframes nwFogDrift {
    to { background-position: -640px 0, 460px 0, -560px 0, 380px 0; }
}
@keyframes nwCandleFlicker {
    0%   { opacity: 0.70; }
    22%  { opacity: 1; }
    38%  { opacity: 0.78; }
    55%  { opacity: 0.95; }
    72%  { opacity: 0.82; }
    88%  { opacity: 1; }
    100% { opacity: 0.88; }
}

/* слой 2: угли — крошечные тлеющие искры медленно поднимаются вверх и уходят */
#send_form::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    z-index: 1 !important;
    pointer-events: none !important;
    background-image:
        radial-gradient(circle 1.6px at 10% 92%, rgba(244, 192, 130, 0.95), transparent 100%),
        radial-gradient(circle 1.1px at 30% 70%, rgba(226, 166, 112, 0.75), transparent 100%),
        radial-gradient(circle 1.8px at 52% 96%, rgba(250, 202, 142, 0.9), transparent 100%),
        radial-gradient(circle 1.1px at 74% 64%, rgba(220, 158, 108, 0.7), transparent 100%),
        radial-gradient(circle 1.4px at 90% 86%, rgba(240, 190, 132, 0.8), transparent 100%) !important;
    background-size: 240px 190px !important;
    background-repeat: repeat !important;
    opacity: 0.75 !important;
    animation: nwEmberRise 22s linear infinite !important;
}
@keyframes nwEmberRise {
    from { background-position: 0 0; }
    to { background-position: -60px -190px; }
}

/* слой 3: бабочка — живая гифка сидит у правого края полосы, в свете свечи;
   крылья машет сама гифка, от нас — только лёгкое покачивание и тёплое свечение */
#nonQRFormItems::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    z-index: 0 !important;
    pointer-events: none !important;
    background-image: url('https://satsvi97.github.io/run-little-mouse/assets/butterfly.gif') !important;
    background-repeat: no-repeat !important;
    background-size: 40px auto !important;
    background-position: right 184px center !important;
    opacity: 0.92 !important;
    filter: drop-shadow(0 0 7px rgba(217, 164, 106, 0.5)) !important;
    /* transform — без !important: иначе анимация его не перебьёт */
    animation: nwButterfly 7s ease-in-out infinite !important;
}
@keyframes nwButterfly {
    0%   { transform: translateY(-1px) rotate(-3deg); }
    50%  { transform: translateY(2px) rotate(3deg); }
    100% { transform: translateY(-1px) rotate(-3deg); }
}
/* на узком экране бабочке тесно — иконки занимают почти всю ширину, убираем */
@media screen and (max-width: 900px) {
    #nonQRFormItems::after { display: none !important; }
}

/* на телефоне подсказка не влезает между иконками — прячем, чтобы не лезла на них */
@media screen and (max-width: 600px) {
    #nonQRFormItems:has(#send_textarea:placeholder-shown)::before { display: none !important; }
}

/* z-index не трогаем ниже подсказки, но свечение оставляем красным */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    z-index: 3 !important;
    text-shadow: 0 0 10px rgba(163, 32, 47, 0.85), 0 0 24px rgba(163, 32, 47, 0.45) !important;
}

@media (prefers-reduced-motion: reduce) {
    #send_form::before, #send_form::after, #nonQRFormItems::after,
    #load-spinner::before, #mes_stop::after { animation: none !important; }
}
